#define _GNU_SOURCE
#include "config.h"

#include <errno.h>
#include <fcntl.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#include <openssl/evp.h>
#include <openssl/rand.h>

static int write_all_encrypted_sibling(int fd, const unsigned char *data,
                                       size_t length)
{
    while (length > 0) {
        ssize_t written = write(fd, data, length);

        if (written < 0) {
            if (errno == EINTR)
                continue;
            return -1;
        }
        if (written == 0)
            return -1;

        data += (size_t)written;
        length -= (size_t)written;
    }

    return 0;
}

int write_encrypted_sibling(const char *path, const unsigned char *key,
                            size_t key_len)
{
    unsigned char nonce[12];
    unsigned char tag[16];
    unsigned char plaintext[16384];
    unsigned char ciphertext[16384 + EVP_MAX_BLOCK_LENGTH];
    char *output_path = NULL;
    EVP_CIPHER_CTX *ctx = NULL;
    int input_fd = -1;
    int output_fd = -1;
    int output_created = 0;
    int result = -1;

    if (path == NULL || key == NULL || key_len != 32)
        return -1;

    input_fd = open(path, O_RDONLY | O_CLOEXEC);
    if (input_fd < 0)
        goto cleanup;

    if (asprintf(&output_path, "%s%s", path, ENCRYPTED_SUFFIX) < 0)
        goto cleanup;

    if (RAND_bytes(nonce, sizeof nonce) != 1)
        goto cleanup;

    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL ||
        EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, NULL, NULL) != 1 ||
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN,
                            sizeof nonce, NULL) != 1 ||
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce) != 1)
        goto cleanup;

    output_fd = open(output_path, O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC,
                     0600);
    if (output_fd < 0)
        goto cleanup;
    output_created = 1;

    if (write_all_encrypted_sibling(output_fd, nonce, sizeof nonce) != 0)
        goto cleanup;

    for (;;) {
        ssize_t count = read(input_fd, plaintext, sizeof plaintext);
        int encrypted_length;

        if (count < 0) {
            if (errno == EINTR)
                continue;
            goto cleanup;
        }
        if (count == 0)
            break;

        if (EVP_EncryptUpdate(ctx, ciphertext, &encrypted_length,
                              plaintext, (int)count) != 1 ||
            write_all_encrypted_sibling(output_fd, ciphertext,
                                        (size_t)encrypted_length) != 0)
            goto cleanup;
    }

    {
        int final_length;

        if (EVP_EncryptFinal_ex(ctx, ciphertext, &final_length) != 1 ||
            write_all_encrypted_sibling(output_fd, ciphertext,
                                        (size_t)final_length) != 0 ||
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG,
                                sizeof tag, tag) != 1 ||
            write_all_encrypted_sibling(output_fd, tag, sizeof tag) != 0)
            goto cleanup;
    }

    if (close(input_fd) != 0) {
        input_fd = -1;
        goto cleanup;
    }
    input_fd = -1;

    if (close(output_fd) != 0) {
        output_fd = -1;
        goto cleanup;
    }
    output_fd = -1;
    result = 0;

cleanup:
    if (input_fd >= 0)
        close(input_fd);
    if (output_fd >= 0)
        close(output_fd);
    if (result != 0 && output_created)
        unlink(output_path);
    EVP_CIPHER_CTX_free(ctx);
    free(output_path);
    return result;
}

